"""Frozen semantic, structural, and media checks for merged formal reports."""

from __future__ import annotations

import copy
import hashlib
import json
from collections import Counter
from pathlib import Path
from typing import Final

from scripts.acceptance.acceptance_types import JsonDict, JsonValue
from scripts.acceptance.deep_compare_word import docx_content_signature, inspect_docx
from scripts.acceptance.deep_compare_word_archive import (
    archive_media_passed,
    frozen_static_hashes,
    media_roles,
)
from scripts.acceptance.deep_compare_word_media import (
    indexed_hashes,
    module_hashes,
    structured_media_passed,
)
from src.aisia_medical_report.twelve_delivery_contract import (
    WordDeliveryContractError,
    resolve_artifact,
    validate_index_media,
)


CASES: Final = ("clinic28-25", "clinic28-09", "clinic28-23")
MODULE_BOOKMARKS: Final = {f"module_{index:02d}" for index in range(1, 12)}


def _mapping(value: JsonValue | None) -> dict[str, JsonValue]:
    return value if isinstance(value, dict) else {}


def _load_json(path: Path) -> JsonDict:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise WordDeliveryContractError("formal structured JSON must be an object")
    return value


def semantic_signature(payload: JsonDict) -> str:
    """Hash frozen wording/scores/recommendations while excluding bound media."""

    normalized = copy.deepcopy(payload)
    subject = _mapping(normalized.get("受检者信息"))
    subject.pop("姓名或编号", None)
    source = _mapping(normalized.get("标准采集图像"))
    for key in ("path", "sha256", "size_bytes"):
        source.pop(key, None)
    modules = normalized.get("检测模块")
    if isinstance(modules, list):
        for module_value in modules:
            module = _mapping(module_value)
            result_images = module.get("结果图")
            if isinstance(result_images, list):
                module["结果图"] = ["<BOUND_MEDIA>" for _ in result_images]
            groups = module.get("医生结果分组")
            if isinstance(groups, list):
                for group_value in groups:
                    group = _mapping(group_value)
                    images = group.get("images")
                    if isinstance(images, list):
                        for image_value in images:
                            image = _mapping(image_value)
                            for key in ("path", "sha256", "size_bytes"):
                                image.pop(key, None)
    encoded = json.dumps(
        normalized,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _doc_contract(
    generated: Path,
    approved: Path,
    role: str,
    all_dynamic: set[str],
    expected_dynamic: set[str],
    subjects: tuple[str, ...] = (),
    generated_roles: dict[str, str] | None = None,
    approved_static_hashes: set[str] | None = None,
) -> JsonDict:
    report = inspect_docx(generated)
    report["path"] = generated.name
    baseline = inspect_docx(approved)
    expected_bookmarks = {
        "user_overview" if role == "user" else "doctor_overview",
        "report_toc",
        *MODULE_BOOKMARKS,
    }
    media = report.get("media")
    media_hashes = [
        str(_mapping(value).get("sha256"))
        for value in media
        if isinstance(media, list) and isinstance(value, dict)
    ] if isinstance(media, list) else []
    expected_counter = Counter({digest: 1 for digest in expected_dynamic})
    actual_counter = Counter(
        digest for digest in media_hashes if digest in all_dynamic
    )
    media_multiset_passed = archive_media_passed(
        media,
        baseline.get("media"),
        generated_roles,
        approved_static_hashes,
    )
    return {
        **report,
        "approved_bookmarks_passed": set(report.get("bookmark_names", [])) == expected_bookmarks,
        "table_layout_passed": report.get("table_shapes") == baseline.get("table_shapes"),
        "embedded_dynamic_media_passed": (
            actual_counter == expected_counter and media_multiset_passed
        ),
        "embedded_media_multiset_passed": media_multiset_passed,
        "content_signature_passed": docx_content_signature(
            generated, subjects, normalize_image_targets=True
        ) == docx_content_signature(
            approved, subjects, normalize_image_targets=True
        ),
    }


def inspect_formal_word_tree(run_root: Path, baseline_root: Path) -> JsonDict:
    samples: list[JsonValue] = []
    reports: list[JsonValue] = []
    index_paths = sorted(run_root.rglob("十二项检测结果索引.json"))
    user_static = frozen_static_hashes(baseline_root, "用户精简版") if index_paths else set()
    doctor_static = frozen_static_hashes(baseline_root, "医生详细版") if index_paths else set()
    for index_path in index_paths:
        sample_root = index_path.parent
        case_id = next((case for case in CASES if case in sample_root.name), "")
        index = _load_json(index_path)
        try:
            validate_index_media(index, sample_root)
            report_root = sample_root / "正式报告"
            generated_structured = next(report_root.glob("*_正式结构化数据.json"))
            structured = _load_json(generated_structured)
            generated_roles = media_roles(structured, report_root)
            indexed = indexed_hashes(index)
            expected_modules = module_hashes(indexed)
            source = _mapping(structured.get("标准采集图像"))
            source_sha = str(source.get("sha256"))
            subjects = (
                str(_mapping(structured.get("受检者信息")).get("姓名或编号", "")),
                case_id,
            )
            all_dynamic = {source_sha, *(digest for values in expected_modules.values() for digest in values)}
            user_dynamic = {source_sha, *(
                digest for module_id, values in expected_modules.items()
                for digest in (values[:2] if module_id == "02" else values[:1])
            )}
            formal = _mapping(index.get("formal_reports"))
            user = resolve_artifact(sample_root, str(formal.get("user_docx")))
            doctor = resolve_artifact(sample_root, str(formal.get("doctor_docx")))
            user_report = _doc_contract(
                user,
                baseline_root / case_id / "正式交付" / f"AISIA_{case_id}_用户精简版.docx",
                "user",
                all_dynamic,
                user_dynamic,
                subjects,
                generated_roles,
                user_static,
            )
            doctor_report = _doc_contract(
                doctor,
                baseline_root / case_id / "正式交付" / f"AISIA_{case_id}_医生详细版.docx",
                "doctor",
                all_dynamic,
                all_dynamic,
                subjects,
                generated_roles,
                doctor_static,
            )
            reports.extend((user_report, doctor_report))
            passed = (
                structured_media_passed(report_root, structured, expected_modules)
                and all(
                    _mapping(report).get(key) is True
                    for report in (user_report, doctor_report)
                    for key in (
                        "valid_docx",
                        "approved_bookmarks_passed",
                        "table_layout_passed",
                        "embedded_dynamic_media_passed",
                        "embedded_media_multiset_passed",
                        "content_signature_passed",
                    )
                )
            )
        except (
            OSError,
            StopIteration,
            WordDeliveryContractError,
            KeyError,
            IndexError,
            ValueError,
            TypeError,
        ):
            passed = False
        samples.append({"case_id": case_id, "formal_equivalence_passed": passed})
    return {
        "docx_count": len(list(run_root.rglob("*.docx"))),
        "reports": reports,
        "samples": samples,
        "merged_formal_contract_passed": len(samples) == 3
        and len(reports) == 6
        and all(_mapping(value).get("formal_equivalence_passed") is True for value in samples),
    }
"""DOCX structural and leak inspection without rendering or mutation."""

from __future__ import annotations

import hashlib
import json
import posixpath
import re
from pathlib import Path
from typing import Final
from xml.etree import ElementTree
from zipfile import BadZipFile, ZipFile

from scripts.acceptance.acceptance_types import JsonDict, JsonValue


WORD_NS: Final = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
PATH_PATTERNS: Final = (
    re.compile(r"/home/[^\s<]+"),
    re.compile(r"/tmp/[^\s<]+"),
    re.compile(r"[A-Za-z]:\\[^\s<]+"),
)


def _sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _leaks(text: str) -> list[str]:
    return sorted({match.group(0) for pattern in PATH_PATTERNS for match in pattern.finditer(text)})


def docx_content_signature(
    path: Path,
    subjects: tuple[str, ...] = (),
    media_roles: dict[str, str] | None = None,
    normalize_image_targets: bool = False,
) -> str:
    """Hash visible text, table structure, bookmarks, and relationships."""

    with ZipFile(path) as archive:
        document = ElementTree.fromstring(archive.read("word/document.xml"))
        relationship_rows: list[tuple[str, str, str, str]] = []
        if "word/_rels/document.xml.rels" in archive.namelist():
            relationships = ElementTree.fromstring(
                archive.read("word/_rels/document.xml.rels")
            )
            for relationship in relationships:
                relation_type = relationship.get("Type", "")
                target = relationship.get("Target", "")
                if relation_type.endswith("/image"):
                    if normalize_image_targets:
                        target = "<IMAGE>"
                    elif media_roles is not None:
                        archive_name = posixpath.normpath(f"word/{target}")
                        digest = _sha256(archive.read(archive_name))
                        target = media_roles.get(digest, f"static:{digest}")
                relationship_rows.append(
                    (
                        relationship.get("Id", ""),
                        relation_type,
                        target,
                        relationship.get("TargetMode", ""),
                    )
                )
    visible = [
        "".join(node.text or "" for node in paragraph.iter(f"{WORD_NS}t"))
        for paragraph in document.iter(f"{WORD_NS}p")
    ]
    for subject in subjects:
        if subject:
            visible = [text.replace(subject, "<SUBJECT>") for text in visible]
    bookmarks = sorted(
        item.get(f"{WORD_NS}name") or ""
        for item in document.iter(f"{WORD_NS}bookmarkStart")
        if (item.get(f"{WORD_NS}name") or "") != "_GoBack"
    )
    table_shapes = [
        [len(list(table.findall(f"{WORD_NS}tr"))), *[
            len(list(row.findall(f"{WORD_NS}tc")))
            for row in table.findall(f"{WORD_NS}tr")
        ]]
        for table in document.iter(f"{WORD_NS}tbl")
    ]
    payload = json.dumps(
        {
            "visible": visible,
            "bookmarks": bookmarks,
            "tables": table_shapes,
            "relationships": sorted(relationship_rows),
        },
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def inspect_docx(path: Path) -> JsonDict:
    """Return chapters, tables, bookmarks, media hashes, and path leaks."""

    try:
        with ZipFile(path) as archive:
            names = archive.namelist()
            document_bytes = archive.read("word/document.xml")
            xml_texts = [
                archive.read(name).decode("utf-8", errors="replace")
                for name in names
                if name.endswith((".xml", ".rels"))
            ]
            media: list[JsonValue] = [
                {
                    "path": name,
                    "size_bytes": len(data),
                    "sha256": _sha256(data),
                }
                for name in sorted(names)
                if name.startswith("word/media/")
                for data in (archive.read(name),)
            ]
    except (BadZipFile, KeyError) as exc:
        return {"path": str(path), "valid_docx": False, "error": str(exc)}
    root = ElementTree.fromstring(document_bytes)
    chapters = 0
    for paragraph in root.iter(f"{WORD_NS}p"):
        styles = paragraph.findall(f".//{WORD_NS}pStyle")
        if any((style.get(f"{WORD_NS}val") or "").lower().startswith("heading") for style in styles):
            chapters += 1
    bookmarks = [
        item
        for item in root.iter(f"{WORD_NS}bookmarkStart")
        if (item.get(f"{WORD_NS}name") or "") != "_GoBack"
    ]
    table_shapes = [
        [len(list(table.findall(f"{WORD_NS}tr"))), *[
            len(list(row.findall(f"{WORD_NS}tc")))
            for row in table.findall(f"{WORD_NS}tr")
        ]]
        for table in root.iter(f"{WORD_NS}tbl")
    ]
    module_bookmarks = [
        item for item in bookmarks if (item.get(f"{WORD_NS}name") or "").startswith("module_")
    ]
    return {
        "path": str(path),
        "valid_docx": True,
        "sha256": _sha256(path.read_bytes()),
        "chapter_count": len(module_bookmarks) or chapters,
        "heading_count": chapters,
        "table_count": len(list(root.iter(f"{WORD_NS}tbl"))),
        "table_shapes": table_shapes,
        "bookmark_count": len(bookmarks),
        "bookmark_names": [item.get(f"{WORD_NS}name") or "" for item in bookmarks],
        "media": media,
        "path_leaks": sorted({leak for text in xml_texts for leak in _leaks(text)}),
    }


def inspect_word_tree(root: Path) -> JsonDict:
    reports: list[JsonDict] = []
    for path in sorted(root.rglob("*.docx")):
        report = inspect_docx(path)
        report["path"] = path.relative_to(root).as_posix()
        reports.append(report)
    output_image_hashes = {
        _sha256(path.read_bytes())
        for path in root.rglob("*")
        if path.is_file() and path.suffix.lower() in {".jpg", ".jpeg", ".png"}
    }
    for report in reports:
        media = report.get("media")
        media_hashes = {
            str(item.get("sha256"))
            for item in media
            if isinstance(media, list) and isinstance(item, dict)
        } if isinstance(media, list) else set()
        report["media_hashes_found_in_output"] = sorted(
            media_hashes & output_image_hashes
        )
        report["media_hash_match_count"] = len(media_hashes & output_image_hashes)
    return {
        "docx_count": len(reports),
        "reports": reports,
        "path_leak_count": sum(len(report.get("path_leaks", [])) for report in reports),
        "merged_formal_contract_passed": bool(reports)
        and all(
            report.get("chapter_count") == 11
            and report.get("bookmark_count") == 13
            and not report.get("path_leaks")
            for report in reports
        ),
    }


def scan_output_path_leaks(root: Path) -> list[JsonValue]:
    findings: list[JsonValue] = []
    text_suffixes = {".json", ".csv", ".md", ".txt", ".html", ".xml"}
    for path in sorted(root.rglob("*")):
        if not path.is_file():
            continue
        if path.suffix.lower() == ".docx":
            report = inspect_docx(path)
            leaks = report.get("path_leaks", [])
        elif path.suffix.lower() in text_suffixes:
            leaks = _leaks(path.read_text(encoding="utf-8", errors="replace"))
        else:
            continue
        if leaks:
            findings.append({"path": path.relative_to(root).as_posix(), "leaks": leaks})
    return findings

"""Dynamic-role and frozen-static media checks for formal DOCX archives."""

from __future__ import annotations

from collections import Counter
from pathlib import Path

from scripts.acceptance.acceptance_types import JsonDict, JsonValue
from scripts.acceptance.deep_compare_word import inspect_docx
from src.aisia_medical_report.twelve_delivery_contract import (
    WordDeliveryContractError,
    resolve_artifact,
    sha256,
)


def _mapping(value: JsonValue | None) -> dict[str, JsonValue]:
    return value if isinstance(value, dict) else {}


def _hashes(media: JsonValue | None) -> list[str]:
    return [
        str(_mapping(value).get("sha256"))
        for value in media
        if isinstance(media, list) and isinstance(value, dict)
    ] if isinstance(media, list) else []


def media_roles(payload: JsonDict, root: Path) -> dict[str, str]:
    roles: dict[str, str] = {}
    source = _mapping(payload.get("标准采集图像"))
    source_path = source.get("path")
    source_sha = source.get("sha256")
    if not isinstance(source_path, str) or not isinstance(source_sha, str):
        raise WordDeliveryContractError("formal source media is incomplete")
    if sha256(resolve_artifact(root, source_path)) != source_sha:
        raise WordDeliveryContractError("formal source media SHA256 mismatch")
    roles[source_sha] = "source"
    modules = payload.get("检测模块")
    if not isinstance(modules, list):
        raise WordDeliveryContractError("formal modules are incomplete")
    for module_value in modules:
        module = _mapping(module_value)
        module_id = str(module.get("模块编号", ""))
        images = module.get("结果图")
        if not isinstance(images, list):
            raise WordDeliveryContractError("formal module media is incomplete")
        for index, relative in enumerate(images, start=1):
            if not isinstance(relative, str):
                raise WordDeliveryContractError("formal module media path is invalid")
            digest = sha256(resolve_artifact(root, relative))
            role = f"module:{module_id}:{index}"
            if digest in roles and roles[digest] != role:
                raise WordDeliveryContractError("formal module media roles are duplicated")
            roles[digest] = role
    return roles


def frozen_static_hashes(baseline_root: Path, report_label: str) -> set[str]:
    reports = sorted(
        baseline_root.glob(f"clinic28-*/正式交付/*_{report_label}.docx")
    )
    if len(reports) != 3:
        raise WordDeliveryContractError("frozen formal report set is incomplete")
    hash_sets = [set(_hashes(inspect_docx(path).get("media"))) for path in reports]
    return set.intersection(*hash_sets)


def archive_media_passed(
    generated_media: JsonValue | None,
    approved_media: JsonValue | None,
    generated_roles: dict[str, str] | None,
    approved_static_hashes: set[str] | None,
) -> bool:
    generated = _hashes(generated_media)
    approved = _hashes(approved_media)
    if generated_roles is None or approved_static_hashes is None:
        return Counter(generated) == Counter(approved)
    generated_static = Counter(
        digest for digest in generated if digest not in generated_roles
    )
    approved_static = Counter(
        digest for digest in approved if digest in approved_static_hashes
    )
    return len(generated) == len(approved) and generated_static == approved_static
"""Exact module and doctor-group media role validation for formal payloads."""

from __future__ import annotations

from pathlib import Path

from scripts.acceptance.acceptance_types import JsonDict, JsonValue
from src.aisia_medical_report.twelve_delivery_contract import resolve_artifact, sha256


def _mapping(value: JsonValue | None) -> dict[str, JsonValue]:
    return value if isinstance(value, dict) else {}


def indexed_hashes(index: JsonDict) -> dict[str, list[str]]:
    items = _mapping(index.get("items"))
    return {
        item_id: [
            str(_mapping(image).get("sha256"))
            for image in _mapping(item_value).get("images", [])
            if isinstance(image, dict)
        ]
        for item_id, item_value in items.items()
    }


def module_hashes(indexed: dict[str, list[str]]) -> dict[str, list[str]]:
    wrinkle = indexed["wrinkle"]
    return {
        "01": [indexed["pores"][0]],
        "02": [indexed["surface_gloss"][0], indexed["porphyrin"][0]],
        "03": [indexed["brown"][0], indexed["spots"][0], indexed["uv_spots"][0]],
        "04": [indexed["redness"][0]],
        "05": [indexed["vascular"][0]],
        "06": [indexed["acne"][0]],
        "07": [wrinkle[0]],
        "08": [wrinkle[1]],
        "09": [wrinkle[2]],
        "10": [indexed["texture"][0]],
        "11": [indexed["contour_firmness"][0]],
    }


def _path_hashes(report_root: Path, values: JsonValue | None) -> list[str]:
    if not isinstance(values, list):
        return []
    return [
        sha256(resolve_artifact(report_root, value))
        for value in values
        if isinstance(value, str)
    ]


def _expected_group_hashes(
    module_id: str,
    title: str,
    expected: dict[str, list[str]],
) -> list[str]:
    if module_id == "02":
        return expected[module_id][:1] if "油光" in title else expected[module_id][1:] if "荧光" in title else []
    if module_id == "03":
        return expected[module_id][1:2] if "可见" in title else expected[module_id][2:] if "UV" in title else expected[module_id][:1] if "Brown" in title else []
    if module_id == "04":
        return expected[module_id] if "强度" in title else []
    if module_id in {"05", "07", "11"}:
        return expected[module_id]
    if module_id == "10":
        return expected[module_id] if "纹理" in title else []
    return []


def structured_media_passed(
    report_root: Path,
    structured: JsonDict,
    expected: dict[str, list[str]],
) -> bool:
    modules_value = structured.get("检测模块")
    if not isinstance(modules_value, list):
        return False
    modules = {
        str(_mapping(value).get("模块编号")): _mapping(value)
        for value in modules_value
    }
    if set(modules) != set(expected):
        return False
    for module_id, hashes in expected.items():
        module = modules[module_id]
        if _path_hashes(report_root, module.get("结果图")) != hashes:
            return False
        groups = module.get("医生结果分组")
        if not isinstance(groups, list):
            continue
        for group_value in groups:
            group = _mapping(group_value)
            images = group.get("images")
            paths = [
                _mapping(image).get("path")
                for image in images
