"""Produce machine JSON and human Markdown for baseline-versus-merged evidence."""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

from pydantic import TypeAdapter

PROJECT_ROOT = Path(__file__).resolve().parents[2]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from scripts.acceptance.acceptance_types import JsonValue
from scripts.acceptance.deep_compare_contracts import (
    audit_manifest_staleness,
    compare_worker_bundles,
)
from scripts.acceptance.deep_compare_inventory import (
    IMAGE_SUFFIXES,
    compare_image_trees,
    compare_tracked_files,
    duplicate_file_groups,
    inventory_tree,
)
from scripts.acceptance.deep_compare_structured import compare_csv_trees, compare_json_trees
from scripts.acceptance.deep_compare_types import ComparisonRequest, DeepReport
from scripts.acceptance.deep_compare_verdict import evaluate_sections
from scripts.acceptance.deep_compare_word import inspect_word_tree, scan_output_path_leaks
from scripts.acceptance.deep_compare_word_formal import inspect_formal_word_tree


JSON_ADAPTER = TypeAdapter(JsonValue)


def _load_bundles(root: Path) -> list[tuple[str, dict[str, JsonValue]]]:
    bundles: list[tuple[str, dict[str, JsonValue]]] = []
    for path in sorted(root.rglob("cloud_response_bundle.json")):
        value = JSON_ADAPTER.validate_json(path.read_text(encoding="utf-8"))
        if isinstance(value, dict):
            bundles.append((path.parent.name, value))
    return bundles


def _contract_sections(request: ComparisonRequest) -> tuple[JsonValue, JsonValue, JsonValue, JsonValue]:
    baseline = dict(_load_bundles(request.baseline_cloud))
    merged = dict(_load_bundles(request.merged_cloud))
    comparisons: list[JsonValue] = []
    for case_id in sorted(set(baseline) & set(merged)):
        comparison = compare_worker_bundles(baseline[case_id], merged[case_id])
        added_three = comparison.get("added_three")
        if isinstance(added_three, dict):
            for item in added_three.values():
                if not isinstance(item, dict):
                    continue
                overlay = item.get("overlay")
                item["overlay_exists"] = isinstance(overlay, str) and (
                    request.merged_cloud / "simulated_oss" / overlay
                ).is_file()
        comparisons.append({"case_id": case_id, **comparison})
    first_baseline = next(iter(baseline.values()), {})
    staleness = audit_manifest_staleness(request.baseline_root, first_baseline)
    acne = [item["acne_v1_to_v2"] for item in comparisons if isinstance(item, dict)]
    added = [item["added_three"] for item in comparisons if isinstance(item, dict)]
    return comparisons, staleness, acne, added


def build_deep_report(request: ComparisonRequest) -> DeepReport:
    worker, staleness, acne, added = _contract_sections(request)
    sections: dict[str, JsonValue] = {
        "tracked_files": compare_tracked_files(request.baseline_root, request.merged_root),
        "file_tree": {
            "baseline_run": {
                "files": inventory_tree(request.baseline_run),
                "duplicate_image_groups": duplicate_file_groups(
                    request.baseline_run, IMAGE_SUFFIXES
                ),
            },
            "merged_run": {
                "files": inventory_tree(request.merged_run),
                "duplicate_image_groups": duplicate_file_groups(
                    request.merged_run, IMAGE_SUFFIXES, "十二项检测"
                ),
            },
            "baseline_cloud": {"files": inventory_tree(request.baseline_cloud)},
            "merged_cloud": {"files": inventory_tree(request.merged_cloud)},
        },
        "images": {
            "run": compare_image_trees(request.baseline_run, request.merged_run),
            "cloud": compare_image_trees(request.baseline_cloud, request.merged_cloud),
        },
        "json": {
            "run": compare_json_trees(request.baseline_run, request.merged_run),
            "cloud": compare_json_trees(request.baseline_cloud, request.merged_cloud),
        },
        "csv_xlsx": {
            "run": compare_csv_trees(request.baseline_run, request.merged_run),
            "cloud": compare_csv_trees(request.baseline_cloud, request.merged_cloud),
            "xlsx_policy": "forbidden_by_final_contract",
        },
        "worker_contracts": worker,
        "baseline_manifest_staleness": staleness,
        "acne_v1_to_v2": acne,
        "added_three": added,
        "word": {
            "baseline": inspect_word_tree(request.baseline_run),
            "merged": inspect_formal_word_tree(
                request.merged_run,
                request.formal_baseline_root,
            ),
        },
        "path_leaks": {
            "baseline_run": scan_output_path_leaks(request.baseline_run),
            "merged_run": scan_output_path_leaks(request.merged_run),
            "baseline_cloud": scan_output_path_leaks(request.baseline_cloud),
            "merged_cloud": scan_output_path_leaks(request.merged_cloud),
        },
    }
    return DeepReport(
        schema="aisia_deep_comparison_v1",
        sections=sections,
        verdict=evaluate_sections(sections),
    )


def write_deep_report(report: DeepReport, json_path: Path, markdown_path: Path) -> None:
    json_path.parent.mkdir(parents=True, exist_ok=True)
    json_path.write_text(
        json.dumps(report.as_json(), ensure_ascii=False, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )
    titles = {
        "tracked_files": "Tracked files",
        "file_tree": "File tree",
        "images": "Images",
        "json": "JSON paths, types, and values",
        "csv_xlsx": "CSV cells and XLSX rejection",
        "worker_contracts": "Worker contracts",
        "baseline_manifest_staleness": "Baseline manifest staleness",
        "acne_v1_to_v2": "Acne v1 to v2",
        "added_three": "Added three",
        "word": "Word",
        "path_leaks": "Path leaks",
    }
    lines = [
        "# AISIA baseline vs merged deep comparison",
        "",
        "## Verdict",
        "",
        "```json",
        json.dumps(report.verdict.as_json(), ensure_ascii=False, indent=2),
        "```",
        "",
    ]
    for key, value in report.sections.items():
        lines.extend(
            [
                f"## {titles[key]}",
                "",
                "```json",
                json.dumps(value, ensure_ascii=False, indent=2, allow_nan=False),
                "```",
                "",
            ]
        )
    markdown_path.write_text("\n".join(lines), encoding="utf-8")


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Compare baseline and merged acceptance evidence")
    for name in (
        "baseline-root",
        "merged-root",
        "baseline-run",
        "merged-run",
        "baseline-cloud",
        "merged-cloud",
        "formal-baseline-root",
        "json-output",
        "markdown-output",
    ):
        parser.add_argument(f"--{name}", type=Path, required=True)
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    comparison_root = args.json_output.parent.resolve()
    if args.markdown_output.parent.resolve() != comparison_root:
        print("comparison outputs must share one directory", file=sys.stderr)
        return 2
    comparison_root.mkdir(parents=True, exist_ok=True)
    if any(comparison_root.iterdir()):
        print("comparison output directory must be empty", file=sys.stderr)
        return 2
    request = ComparisonRequest(
        args.baseline_root,
        args.merged_root,
        args.baseline_run,
        args.merged_run,
        args.baseline_cloud,
        args.merged_cloud,
        args.formal_baseline_root,
    )
    report = build_deep_report(request)
    write_deep_report(report, args.json_output, args.markdown_output)
    return 0 if report.verdict.status == "passed" else 1


if __name__ == "__main__":
    raise SystemExit(main())

"""Deterministic file pairing with explicit unmatched and ambiguous evidence."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from scripts.acceptance.acceptance_types import JsonValue


@dataclass(frozen=True, slots=True)
class FilePair:
    baseline: Path
    merged: Path
    match_kind: str


@dataclass(frozen=True, slots=True)
class PairingResult:
    pairs: tuple[FilePair, ...]
    unmatched_baseline: tuple[str, ...]
    unmatched_merged: tuple[str, ...]
    ambiguous: tuple[JsonValue, ...]


def pair_file_trees(
    baseline_root: Path,
    merged_root: Path,
    suffixes: set[str],
) -> PairingResult:
    baseline = sorted(
        path for path in baseline_root.rglob("*")
        if path.is_file() and path.suffix.lower() in suffixes
    )
    merged = sorted(
        path for path in merged_root.rglob("*")
        if path.is_file() and path.suffix.lower() in suffixes
    )
    baseline_by_relative = {
        path.relative_to(baseline_root).as_posix(): path for path in baseline
    }
    merged_by_relative = {
        path.relative_to(merged_root).as_posix(): path for path in merged
    }
    paired_baseline: set[str] = set()
    paired_merged: set[str] = set()
    pairs: list[FilePair] = []
    for relative in sorted(set(baseline_by_relative) & set(merged_by_relative)):
        pairs.append(
            FilePair(
                baseline=baseline_by_relative[relative],
                merged=merged_by_relative[relative],
                match_kind="relative_path",
            )
        )
        paired_baseline.add(relative)
        paired_merged.add(relative)
    baseline_names: dict[str, list[str]] = {}
    merged_names: dict[str, list[str]] = {}
    for relative in sorted(set(baseline_by_relative) - paired_baseline):
        baseline_names.setdefault(Path(relative).name, []).append(relative)
    for relative in sorted(set(merged_by_relative) - paired_merged):
        merged_names.setdefault(Path(relative).name, []).append(relative)
    ambiguous: list[JsonValue] = []
    for basename in sorted(set(baseline_names) & set(merged_names)):
        left = baseline_names[basename]
        right = merged_names[basename]
        if len(left) == 1 and len(right) == 1:
            pairs.append(
                FilePair(
                    baseline=baseline_by_relative[left[0]],
                    merged=merged_by_relative[right[0]],
                    match_kind="unique_basename",
                )
            )
            paired_baseline.add(left[0])
            paired_merged.add(right[0])
        else:
            ambiguous.append(
                {"basename": basename, "baseline": left, "merged": right}
            )
    return PairingResult(
        pairs=tuple(pairs),
        unmatched_baseline=tuple(sorted(set(baseline_by_relative) - paired_baseline)),
        unmatched_merged=tuple(sorted(set(merged_by_relative) - paired_merged)),
        ambiguous=tuple(ambiguous),
    )
"""Path-scoped policy for paired JSON and CSV value changes."""

from __future__ import annotations

import math
from pathlib import Path

from scripts.acceptance.acceptance_types import JsonValue


_NUMERIC_TYPES = {"integer", "number"}
_CRITICAL_JSON_FIELDS = {
    "status",
    "schema_version",
    "metrics_version",
    "score_valid",
    "grade",
}
_IMAGE_VALUE_FIELDS = {
    "image",
    "image_path",
    "main_image",
    "overlay",
    "path",
    "sha256",
}


def _mapping(value: JsonValue | None) -> dict[str, JsonValue]:
    return value if isinstance(value, dict) else {}


def _values(value: JsonValue | None) -> list[JsonValue]:
    return value if isinstance(value, list) else []


def _finite_number(value: JsonValue | None) -> bool:
    return (
        isinstance(value, (int, float))
        and not isinstance(value, bool)
        and math.isfinite(float(value))
    )


def _json_leaf(path: str) -> str:
    return path.rsplit(".", 1)[-1].split("[", 1)[0].lower()


def _is_image_value(path: str) -> bool:
    leaf = _json_leaf(path)
    return leaf in _IMAGE_VALUE_FIELDS or leaf.endswith(("_path", "_sha256", "_overlay"))


def _json_change_allowed(
    difference: dict[str, JsonValue],
    comparison: dict[str, JsonValue],
) -> bool:
    merged_path = Path(str(comparison.get("merged_path", ""))).name
    if merged_path == "cloud_response_bundle.json":
        return True
    baseline = _mapping(difference.get("baseline"))
    merged = _mapping(difference.get("merged"))
    if not baseline or not merged:
        return False
    path = str(difference.get("key", ""))
    if _json_leaf(path) in _CRITICAL_JSON_FIELDS:
        return False
    baseline_type = baseline.get("type")
    merged_type = merged.get("type")
    if baseline_type != merged_type:
        return False
    if baseline_type in _NUMERIC_TYPES:
        return _finite_number(baseline.get("value")) and _finite_number(
            merged.get("value")
        )
    if baseline_type == "string" and _is_image_value(path):
        return bool(baseline.get("value")) and bool(merged.get("value"))
    return False


def json_difference_policy(
    comparisons: list[JsonValue],
) -> tuple[list[str], bool]:
    errors: list[str] = []
    allowed = False
    for comparison_value in comparisons:
        comparison = _mapping(comparison_value)
        for difference_value in _values(comparison.get("differences")):
            difference = _mapping(difference_value)
            if _json_change_allowed(difference, comparison):
                allowed = True
            else:
                errors.append(
                    f"{comparison.get('merged_path', '<unknown>')}:{difference.get('key', '<unknown>')}"
                )
    return errors, allowed


def _csv_number(value: JsonValue | None) -> bool:
    if not isinstance(value, str) or not value.strip():
        return False
    try:
        return math.isfinite(float(value))
    except ValueError:
        return False


def csv_difference_policy(
    comparisons: list[JsonValue],
) -> tuple[list[str], bool]:
    errors: list[str] = []
    allowed = False
    for comparison_value in comparisons:
        comparison = _mapping(comparison_value)
        for difference_value in _values(comparison.get("differences")):
            difference = _mapping(difference_value)
            baseline = _mapping(difference.get("baseline"))
            merged = _mapping(difference.get("merged"))
            cell = str(difference.get("key", ""))
            if (
                baseline
                and merged
                and not cell.startswith("R1C")
                and baseline.get("type") == "string"
                and merged.get("type") == "string"
                and _csv_number(baseline.get("value"))
                and _csv_number(merged.get("value"))
            ):
                allowed = True
            else:
                errors.append(
                    f"{comparison.get('merged_path', '<unknown>')}:{cell or '<unknown>'}"
                )
    return errors, allowed
